import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice enriches multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for wrong format', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '10-07-2026',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026/10/07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for empty array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for zero or negative qty', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  }), { ok: false, error: 'QTY_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -1 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice returns copies of data', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  lines[0].qty = 999;
  assert.equal(r.value.lines[0].qty, 1);
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 2, unitPrice: 8500 }), 17000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1250 }), 1250);
  assert.equal(lineTotal({ qty: 10, unitPrice: 100 }), 1000);
});

test('invoiceTotals sums line totals for a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 3 * 8500);
  assert.equal(totals.total, 3 * 8500);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expected = (2 * 8500) + (3 * 9500);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals calculates correctly with multiple varied items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expected = (5 * 8500) + (1 * 120000) + (100 * 50);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 1);
  assert.equal(r2.value.lines[0].qty, 2);
});

test('addLine increases qty for an existing SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 5);
});

test('addLine reports QTY_INVALID for bad quantities', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.deepEqual(addLine(r.value, { sku: 'NOPE', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const nonDraft = { ...r.value, status: 'sent' };
  assert.deepEqual(addLine(nonDraft, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const originalLineCount = r.value.lines.length;
  addLine(r.value, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(r.value.lines.length, originalLineCount);
});

test('removeLine removes a line from an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const r2 = removeLine(r.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for missing SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.deepEqual(removeLine(r.value, 'NOPE'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.deepEqual(removeLine(r.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const nonDraft = { ...r.value, status: 'sent' };
  assert.deepEqual(removeLine(nonDraft, 'DEV-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const originalLineCount = r.value.lines.length;
  removeLine(r.value, 'DEV-HOUR');
  assert.equal(r.value.lines.length, originalLineCount);
});
